#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
#include <numbers>
#include <cmath>
void check(bool ok,const QString& text){if(!ok)throw std::runtime_error(text.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
    CadDocument d;auto sketch=SketchGeometry::newFeature(d.authored()["documentId"].toString(),"XZ","Radial fixture");sketch=SketchGeometry::addRectangle(sketch,{{"u1Mm",10},{"v1Mm",0},{"u2Mm",20},{"v2Mm",15}});sketch=SketchGeometry::addLine(sketch,{{"u1Mm",0},{"v1Mm",-5},{"u2Mm",0},{"v2Mm",20}});auto axis=sketch["parameters"].toObject()["entities"].toArray().last().toObject();sketch=SketchGeometry::setConstruction(sketch,{{"entityIds",QJsonArray{axis["id"]}},{"construction",true}}).feature;auto candidate=SketchGeometry::replaceFeature(d.authored(),sketch);check(d.commit(candidate,"Source").isEmpty(),"source commit");
    auto args=QJsonObject{{"sketchId",sketch["id"]},{"profileId",d.sketches().front().profiles.front().profileId},{"axisEntityId",axis["id"]}};const auto source=d.authored();candidate=CadDocument::revolveCandidate(source,args);check(d.commit(candidate,"Full").isEmpty(),d.lastEvaluationError()["message"].toString());auto volume=[&]{return d.bodies().front().summary["volumeMm3"].toDouble();};check(std::abs(volume()-4500*std::numbers::pi)<1e-5,"Full annular volume");auto body=d.bodies().front();check(body.supportFaces.empty(),"Full has no sweep caps");args["featureId"]=body.featureId;args["extent"]="partial";args["angleDeg"]=70;check(d.commit(CadDocument::revolveCandidate(d.authored(),args),"Partial").isEmpty(),"partial commit");check(std::abs(volume()-875*std::numbers::pi)<1e-5,"70 degree volume");check(d.bodies().front().supportFaces.size()==2,"partial exact caps");const auto partial=d.authored();const auto cap=d.bodies().front().supportFaces.back().faceId;args["angleDeg"]=180;check(d.commit(CadDocument::revolveCandidate(d.authored(),args),"Half").isEmpty(),"half commit");check(std::abs(volume()-2250*std::numbers::pi)<1e-5,"Half analytic volume");d.history().undo();check(d.authored()==partial,"exact undo");d.history().redo();check(std::abs(volume()-2250*std::numbers::pi)<1e-5,"redo");
    auto bad=args;bad["axisEntityId"]=CadDocument::newId();const auto accepted=d.authored();const auto revision=d.revision();check(!d.commit(CadDocument::revolveCandidate(accepted,bad),"Missing axis").isEmpty() && d.lastEvaluationError()["code"]=="axis_unavailable" && d.authored()==accepted && d.revision()==revision,"missing axis atomic");
    auto edit=accepted;auto fs=edit["features"].toArray();auto s=fs.first().toObject();auto p=s["parameters"].toObject();auto points=p["points"].toArray();for(int i=0;i<points.size();++i){auto q=points[i].toObject();if(q["id"]==axis["startPointId"] || q["id"]==axis["endPointId"]){q["uMm"]=1;points[i]=q;}}p["points"]=points;s["parameters"]=p;fs[0]=s;edit["features"]=fs;check(d.commit(edit,"Move axis").isEmpty(),"axis edit rebuild");check(std::abs(volume()-2100*std::numbers::pi)<1e-5 && d.bodies().front().bodyId==body.bodyId && d.bodies().front().supportFaces.back().faceId==cap,"axis retained rebuild");
    auto cross=d.authored();fs=cross["features"].toArray();s=fs.first().toObject();p=s["parameters"].toObject();points=p["points"].toArray();for(int i=0;i<points.size();++i){auto q=points[i].toObject();if(q["id"]==axis["startPointId"] || q["id"]==axis["endPointId"]){q["uMm"]=15;points[i]=q;}}p["points"]=points;s["parameters"]=p;fs[0]=s;cross["features"]=fs;const auto before=d.authored();check(!d.commit(cross,"Crossing axis").isEmpty() && d.lastEvaluationError()["code"]=="axis_crosses_profile" && d.authored()==before,"crossing refusal atomic");
    auto changed=before;fs=changed["features"].toArray();s=fs.first().toObject();p=s["parameters"].toObject();points=p["points"].toArray();for(int i=0;i<points.size();++i){auto q=points[i].toObject();if(q["uMm"].toDouble()==20){q["uMm"]=22;points[i]=q;}}p["points"]=points;s["parameters"]=p;fs[0]=s;changed["features"]=fs;check(d.commit(changed,"Profile edit").isEmpty(),"profile edit rebuild");check(std::abs(volume()-2700*std::numbers::pi)<1e-5,"edited radial volume");
    for(double angle:{0.,-70.,360.}){auto invalid=args;invalid["angleDeg"]=angle;bool refused=false;try{CadDocument::revolveCandidate(d.authored(),invalid);}catch(const std::invalid_argument&){refused=true;}check(refused,"invalid partial angle refused");}
    CadDocument normalAxis;auto block=SketchGeometry::newFeature(normalAxis.authored()["documentId"].toString(),"XZ","Boundary axis");block=SketchGeometry::addRectangle(block,{{"u1Mm",0},{"v1Mm",0},{"u2Mm",10},{"v2Mm",15}});check(normalAxis.commit(SketchGeometry::replaceFeature(normalAxis.authored(),block),"Boundary sketch").isEmpty(),"boundary source");auto boundary=block["parameters"].toObject()["entities"].toArray().last().toObject();check(normalAxis.commit(CadDocument::revolveCandidate(normalAxis.authored(),{{"sketchId",block["id"]},{"profileId",normalAxis.sketches().front().profiles.front().profileId},{"axisEntityId",boundary["id"]}}),"Boundary revolve").isEmpty(),"normal boundary line accepted as axis");check(std::abs(normalAxis.bodies().front().summary["volumeMm3"].toDouble()-1500*std::numbers::pi)<1e-5,"boundary cylinder volume");
    QTemporaryDir temp;const auto path=temp.filePath("revolve.alloy");check(d.save(path).isEmpty(),"save");CadDocument reopened;check(reopened.open(path).isEmpty() && reopened.authored()==d.authored() && reopened.bodies().front().bodyId==body.bodyId,"exact reopen");std::cout<<"PASS Full/70/Half, axis/profile edits, caps, atomic refusal, history/storage\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
